#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <number>\n", argv[0]);
        return 1;
    }

    char *endptr;
    long value = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        printf("'%s' is not a valid number\n", argv[1]);
        return 1;
    }

    printf("You entered: %ld\n", value);
    return 0;
}
